#!/usr/bin/env bash
# test_vault_portfolio_written_text.sh — what vault-portfolio's scripts write into a vault is
# the same text on every host.
#
# One vault, and one project's sidecar block, can be rebuilt from one host today and from
# another tomorrow. If a host layer renamed a sentence the scripts write (the sidecar
# sentinel, a roll-up's "regenerated by" line), every switch of host would rewrite every
# committed sidecar block and roll-up. So a host's rewrites may rename what a user reads,
# never what the scripts write.
#
# The test builds the claude, cursor and opencode trees into temp dirs and compares every
# string literal of every shipped script, file by file, across the three. A literal may
# differ only when it is a plugin-internal path to a skill folder or a script (the folders a
# host renames), or when it is one of the messages listed in ALLOWED below, which go to the
# terminal and never into a file. It also checks that a reference quoting a written string
# quotes it the same way on each host, and that the slug table the scripts read is the same.
#
# The build is the planning repo's build.py: $STAGED_PLANNING_ROOT, else a sibling
# ../staged-planning. Without one it says so and checks nothing.
set -u

ROOT="$(cd "$(dirname "$0")/.." && pwd)"
PLANNING="${STAGED_PLANNING_ROOT:-$ROOT/../staged-planning}"
BUILD="$PLANNING/build/build.py"

if [ ! -f "$BUILD" ]; then
    echo "  skip: no planning checkout with build/build.py (set STAGED_PLANNING_ROOT); written text is not compared"
    exit 0
fi

WORK="$(mktemp -d)"
trap 'rm -rf "$WORK"' EXIT

for h in claude opencode cursor; do
    mkdir -p "$WORK/$h"
    if ! out="$(cd "$ROOT" && python3 "$BUILD" --root src/vault-portfolio --host "$h" --no-lock-check --out "$WORK/$h" 2>&1)"; then
        echo "FAIL: the $h build failed:" >&2
        printf '%s\n' "$out" >&2
        exit 1
    fi
done

python3 -I - "$WORK" <<'PY'
import ast
import re
import sys
from pathlib import Path

work = Path(sys.argv[1])
HOSTS = ("claude", "cursor", "opencode")
FAILURES = []

# Messages a script prints to the terminal, never into a file: a host may rename the command
# they name. Keyed by the script's core path and the literal as core spells it.
ALLOWED = {
    ("scripts/records-home.py", "); /vault-portfolio:portfolio rebuild --write refreshes it"),
}
# A path a script joins to reach a sibling: a skill folder name, or a script path under one.
INTERNAL_PATH = re.compile(r"(vault-)?(portfolio|compass)|skills/(vault-)?(portfolio|compass)/scripts/[\w.-]+\.py")


def core_path(rel):
    """The core path of a built file: a host that renames a skill folder ships it at
    skills/vault-<name>/."""
    return re.sub(r"^skills/vault-(portfolio|compass)/", r"skills/\1/", rel)


def shipped(root, suffix):
    files = {}
    for p in sorted(root.rglob(f"*{suffix}")):
        rel = p.relative_to(root).as_posix()
        if "/tests/" in f"/{rel}" or "__pycache__" in rel:
            continue
        files[core_path(rel)] = p
    return files


def literals(path):
    tree = ast.parse(path.read_text(encoding="utf-8"))
    return [(n.lineno, n.value) for n in ast.walk(tree)
            if isinstance(n, ast.Constant) and isinstance(n.value, str)]


py = {h: shipped(work / h, ".py") for h in HOSTS}
md = {h: shipped(work / h, ".md") for h in HOSTS}

# Every host ships the same scripts: a script left out would write nothing on that host,
# and the comparison below would pass by skipping it.
for h in HOSTS[1:]:
    if set(py[h]) != set(py["claude"]):
        FAILURES.append(f"{h} ships other scripts than claude: "
                        f"missing {sorted(set(py['claude']) - set(py[h]))}, "
                        f"extra {sorted(set(py[h]) - set(py['claude']))}")
if not py["claude"]:
    FAILURES.append("the claude build ships no scripts: nothing was compared")

compared = 0
for rel in sorted(py["claude"]):
    base = literals(py["claude"][rel])
    for h in HOSTS[1:]:
        if rel not in py[h]:
            continue
        other = literals(py[h][rel])
        if len(other) != len(base):
            FAILURES.append(f"{h} {rel}: {len(other)} string literals, claude has {len(base)}")
            continue
        for (line, a), (_, b) in zip(base, other):
            compared += 1
            if a == b:
                continue
            if INTERNAL_PATH.fullmatch(a) and INTERNAL_PATH.fullmatch(b):
                continue
            if (rel, a) in ALLOWED:
                continue
            FAILURES.append(f"{h} {rel}:{line}: written text differs from claude\n"
                            f"      claude:   {a!r}\n      {h + ':':9} {b!r}")

# The strings the scripts write that name a command: a reference that quotes one (the
# sidecar sentinel, a roll-up template) must quote it as the script writes it.
written = sorted({a for rel in py["claude"] for _, a in literals(py["claude"][rel])
                  if "/vault-portfolio:" in a and (rel, a) not in ALLOWED})
if not written:
    FAILURES.append("no written string names a command: the reference check compared nothing")
quoted = 0
for rel, path in sorted(md["claude"].items()):
    text = path.read_text(encoding="utf-8")
    for s in written:
        if s not in text:
            continue
        quoted += 1
        for h in HOSTS[1:]:
            if rel not in md[h]:
                continue
            if s not in md[h][rel].read_text(encoding="utf-8"):
                FAILURES.append(f"{h} {rel}: no longer quotes the written string {s!r}")

# The slug table the scripts read and write register names from.
slug = "skills/portfolio/references/domain-slugs.md"
rows = {h: [l for l in md[h][slug].read_text(encoding="utf-8").splitlines() if l.lstrip().startswith("|")]
        for h in HOSTS if slug in md[h]}
for h in HOSTS[1:]:
    if rows.get(h) != rows.get("claude"):
        FAILURES.append(f"{h} {slug}: the slug table differs from claude's")

for f in FAILURES:
    print(f"  FAIL: {f}")
if FAILURES:
    sys.exit(1)
print(f"  ok: {compared} script literals and {quoted} quoted written strings agree across {', '.join(HOSTS)}")
print("ALL OK")
PY
